INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99074, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "烹饪用的炊具，圆形，底部凹。", "primary_collocate": null, "pronunciation": "guō", "ipa": "kwɔ˥", "syllable_count": 1, "sentences": [{"text": "厨房里有一个大锅和两个小碗。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炒菜用哪口锅好？", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个锅很深，可以多放些水。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了新锅，炒蛋不会粘在锅上。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅里有肉，也有青菜。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做汤的时候，要先把锅烧热。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们带着锅去山上做饭。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个锅的盖子丢了，只好用盘子盖上。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把汤从锅里倒进碗里。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，锅很烫，别用手去摸。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "口", "label": "量词"}, {"form": "锅盖", "label": "复合"}, {"form": "炒锅", "label": "复合"}, {"form": "铁锅", "label": "复合"}], "register": "中性", "sense_fingerprint": "烹饪用的圆形、底部凹下的炊具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5e84c5-2a16-4f68-a12b-1f0403cb5795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99074, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "锅", "is_correct": true, "explanation": "锅：烹饪用的圆形炊具，即本词。"}, {"text": "国", "is_correct": false, "explanation": "guó（第二声）与 guō（第一声）声调不同，意思是国家。"}, {"text": "果", "is_correct": false, "explanation": "guǒ（第三声）与 guō（第一声）声调不同，意思是水果。"}, {"text": "过", "is_correct": false, "explanation": "guò（第四声）与 guō（第一声）声调不同，意思是经过。"}], "explanations": {"锅": "锅：烹饪用的圆形炊具，即本词。", "国": "guó（第二声）与 guō（第一声）声调不同，意思是国家。", "果": "guǒ（第三声）与 guō（第一声）声调不同，意思是水果。", "过": "guò（第四声）与 guō（第一声）声调不同，意思是经过。"}, "sentence_index": null, "correct_answer": "锅"}, "level_3": {"options": [{"text": "锅", "is_correct": true, "explanation": "锅：烹饪用的炊具，与“厨房里的器具”语境吻合。"}, {"text": "船", "is_correct": false, "explanation": "语义：厨房里不会有一个大船，与语境不符。"}, {"text": "山", "is_correct": false, "explanation": "语义：厨房里不会有一座大山，与语境不符。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“一个大饭”不成立，“饭”不能用“大”修饰作为器具。"}], "explanations": {"锅": "锅：烹饪用的炊具，与“厨房里的器具”语境吻合。", "船": "语义：厨房里不会有一个大船，与语境不符。", "山": "语义：厨房里不会有一座大山，与语境不符。", "饭": "搭配：“一个大饭”不成立，“饭”不能用“大”修饰作为器具。"}, "sentence_index": 0, "correct_answer": "锅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用锅写了一封信。", "explanation": "这里应该用〈笔〉。写信要用笔，锅是烹饪用的炊具，不能用来写字。"}, {"text": "妈妈用锅切了一块肉。", "explanation": "这里应该用〈菜刀〉。切肉要用菜刀，锅是烹饪用的炊具，不能用来切肉。"}, {"text": "妈妈用锅洗了脸。", "explanation": "这里应该用〈脸盆〉。洗脸要用脸盆，锅是烹饪用的炊具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99074, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "锅", "is_correct": true, "explanation": "锅：烹饪用的圆形炊具，即本词。"}, {"text": "哥", "is_correct": false, "explanation": "gē 与 guō 韵母 e 与 uo 不同，声调相同（第一声），意思是哥哥。"}, {"text": "个", "is_correct": false, "explanation": "gè 与 guō 韵母 e 与 uo 不同，声调也不同，意思是量词“个”。"}, {"text": "裹", "is_correct": false, "explanation": "guǒ（第三声）与 guō（第一声）声调不同，意思是包住、缠绕。"}], "explanations": {"锅": "锅：烹饪用的圆形炊具，即本词。", "哥": "gē 与 guō 韵母 e 与 uo 不同，声调相同（第一声），意思是哥哥。", "个": "gè 与 guō 韵母 e 与 uo 不同，声调也不同，意思是量词“个”。", "裹": "guǒ（第三声）与 guō（第一声）声调不同，意思是包住、缠绕。"}, "sentence_index": null, "correct_answer": "锅"}, "level_3": {"options": [{"text": "锅", "is_correct": true, "explanation": "锅：烹饪用的炊具，可以随身带去山上做饭。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱笨重且需要用电，不能带到山上做饭。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不能用来做饭，与语境不符。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“带着”接的是可随身携带的东西，不能说带着房子。"}], "explanations": {"锅": "锅：烹饪用的炊具，可以随身带去山上做饭。", "冰箱": "语义：冰箱笨重且需要用电，不能带到山上做饭。", "电视": "语义：电视不能用来做饭，与语境不符。", "房子": "搭配：“带着”接的是可随身携带的东西，不能说带着房子。"}, "sentence_index": 6, "correct_answer": "锅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用锅喝了一杯茶。", "explanation": "这里应该用〈杯子〉。喝茶要用杯子，锅是炊具，不能用来喝茶。"}, {"text": "他用锅扫了地。", "explanation": "这里应该用〈扫帚〉。扫地要用扫帚，锅是炊具，不能用来扫地。"}, {"text": "妈妈用锅量了一杯米。", "explanation": "这里应该用〈量杯〉。量米要用量杯，锅是烹饪用的炊具，不能用来量米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在店里挑了一张铁锅，准备炖鸡。", "corrected_sentence": "妈妈在店里挑了一口铁锅，准备炖鸡。", "error_description": "量词错误。“锅”的量词应为“口”，“张”用于平面的东西，不能用来数锅。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们背着一条锅去河边煮粥。", "corrected_sentence": "他们背着一口锅去河边煮粥。", "error_description": "量词错误。“锅”的量词应为“口”，“条”用于细长的东西，不能用来数锅。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99077, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "晴", "is_correct": true, "explanation": "晴与阴在天气义上互为反义：阴指云多、不见太阳，晴指天空无云、阳光充足。"}, {"text": "厚", "is_correct": false, "explanation": "厚指物体的厚度大，与阴（天上有云）的天气状态无关。"}, {"text": "慢", "is_correct": false, "explanation": "慢指速度低，与阴不构成反义关系。"}, {"text": "深", "is_correct": false, "explanation": "深指颜色浓或距离远，与阴的天气义不构成反义关系。"}], "correct_answer": "晴", "explanations": {"晴": "晴与阴在天气义上互为反义：阴指云多、不见太阳，晴指天空无云、阳光充足。", "厚": "厚指物体的厚度大，与阴（天上有云）的天气状态无关。", "慢": "慢指速度低，与阴不构成反义关系。", "深": "深指颜色浓或距离远，与阴的天气义不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99077, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "晴", "is_correct": true, "explanation": "晴与阴在天气义上互为反义：阴指云多、不见太阳，晴指天空无云、阳光充足。"}, {"text": "高", "is_correct": false, "explanation": "高指位置或程度在上，与阴（天上有云）不构成反义关系。"}, {"text": "软", "is_correct": false, "explanation": "软指质地柔和，与阴不构成反义关系。"}, {"text": "快", "is_correct": false, "explanation": "快指速度高，与阴不构成反义关系。"}], "correct_answer": "晴", "explanations": {"晴": "晴与阴在天气义上互为反义：阴指云多、不见太阳，晴指天空无云、阳光充足。", "高": "高指位置或程度在上，与阴（天上有云）不构成反义关系。", "软": "软指质地柔和，与阴不构成反义关系。", "快": "快指速度高，与阴不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99077, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "阴是天上有云，看不到太阳。", "primary_collocate": null, "pronunciation": "yīn", "ipa": "in˥˥", "syllable_count": 1, "sentences": [{"text": "昨天天气很阴，一点太阳也没有。", "target_word": "阴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上云很多，今天阴得很。", "target_word": "阴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，天阴了，快收衣服吧。", "target_word": "阴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一连三天都是阴的，我心情不太好。", "target_word": "阴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上还有太阳，中午天就阴了。", "target_word": "阴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天又阴又冷，多穿点衣服。", "target_word": "阴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天阴着，也许一会儿会下雨。", "target_word": "阴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里冬天常常很阴，很少看到太阳。", "target_word": "阴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天慢慢阴下来，风也大了。", "target_word": "阴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末天阴，我们就在家看电影。", "target_word": "阴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "阴了", "label": "体标（了）"}, {"form": "阴着", "label": "体标（着）"}, {"form": "阴阴的", "label": "重叠"}, {"form": "陰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "阴：天上有云，看不到太阳（天气）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34a82c9e-092e-40ce-a3d1-76b4efb5b7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99077, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "阴", "is_correct": true, "explanation": "阴（yīn）指天上有云、看不到太阳，是本题的正确答案。"}, {"text": "印", "is_correct": false, "explanation": "yìn（第四声）与 yīn（第一声）声调不同，印 yìn 的意思是印刷、印章。"}, {"text": "饮", "is_correct": false, "explanation": "yǐn（第三声）与 yīn（第一声）声调不同，饮 yǐn 的意思是喝。"}, {"text": "鹰", "is_correct": false, "explanation": "yīng 与 yīn 的韵尾不同（-ng 与 -n），鹰 yīng 指一种猛禽。"}, {"text": "吟", "is_correct": false, "explanation": "yín（第二声）与 yīn（第一声）声调不同，吟 yín 的意思是吟诵、念诗。"}], "explanations": {"阴": "阴（yīn）指天上有云、看不到太阳，是本题的正确答案。", "印": "yìn（第四声）与 yīn（第一声）声调不同，印 yìn 的意思是印刷、印章。", "饮": "yǐn（第三声）与 yīn（第一声）声调不同，饮 yǐn 的意思是喝。", "鹰": "yīng 与 yīn 的韵尾不同（-ng 与 -n），鹰 yīng 指一种猛禽。", "吟": "yín（第二声）与 yīn（第一声）声调不同，吟 yín 的意思是吟诵、念诗。"}, "sentence_index": null, "correct_answer": "阴"}, "level_3": {"options": [{"text": "阴", "is_correct": true, "explanation": "阴指天上有云、看不到太阳，与「一点太阳也没有」相符，是正确答案。"}, {"text": "晴", "is_correct": false, "explanation": "语义：晴指天空无云、阳光充足，与「一点太阳也没有」相矛盾。"}, {"text": "明朗", "is_correct": false, "explanation": "语义：明朗指天气晴好、光线充足，与「一点太阳也没有」相矛盾。"}, {"text": "长", "is_correct": false, "explanation": "搭配：「长」描写长度，不能用来形容天气。"}], "explanations": {"阴": "阴指天上有云、看不到太阳，与「一点太阳也没有」相符，是正确答案。", "晴": "语义：晴指天空无云、阳光充足，与「一点太阳也没有」相矛盾。", "明朗": "语义：明朗指天气晴好、光线充足，与「一点太阳也没有」相矛盾。", "长": "搭配：「长」描写长度，不能用来形容天气。"}, "sentence_index": 0, "correct_answer": "阴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中午阴得刺眼，我们快戴上墨镜吧。", "explanation": "这里应该用〈晴〉。阴指天上云多、看不到太阳，刺眼的强光是晴天的特点。"}, {"text": "天空阴，阳光很好，我们去野餐吧。", "explanation": "这里应该用〈明亮〉。阴指看不到太阳，与「阳光很好」矛盾。"}, {"text": "操场上太阳很大，天却阴得厉害，我们去打球吧。", "explanation": "这里应该用〈晴〉。阴指看不到太阳，与「太阳很大」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99077, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "阴", "is_correct": true, "explanation": "阴（yīn）指天上有云、看不到太阳，是本题的正确答案。"}, {"text": "银", "is_correct": false, "explanation": "yín（第二声）与 yīn（第一声）声调不同，银 yín 的意思是银子。"}, {"text": "引", "is_correct": false, "explanation": "yǐn（第三声）与 yīn（第一声）声调不同，引 yǐn 的意思是引导。"}, {"text": "英", "is_correct": false, "explanation": "yīng 与 yīn 的韵尾不同（-ng 与 -n），英 yīng 的意思是英雄、英国。"}, {"text": "隐", "is_correct": false, "explanation": "yǐn（第三声）与 yīn（第一声）声调不同，隐 yǐn 的意思是藏起来、不显露。"}], "explanations": {"阴": "阴（yīn）指天上有云、看不到太阳，是本题的正确答案。", "银": "yín（第二声）与 yīn（第一声）声调不同，银 yín 的意思是银子。", "引": "yǐn（第三声）与 yīn（第一声）声调不同，引 yǐn 的意思是引导。", "英": "yīng 与 yīn 的韵尾不同（-ng 与 -n），英 yīng 的意思是英雄、英国。", "隐": "yǐn（第三声）与 yīn（第一声）声调不同，隐 yǐn 的意思是藏起来、不显露。"}, "sentence_index": null, "correct_answer": "阴"}, "level_3": {"options": [{"text": "阴", "is_correct": true, "explanation": "阴指天上有云、不见太阳，与「也许一会儿会下雨」的预期相符，是正确答案。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：「热闹」形容场面喧闹，不能用来描述天空的状态。"}, {"text": "高", "is_correct": false, "explanation": "搭配：「高」描写高度，不能用来描述天空的天气状态。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：干燥指空气缺水，与「也许会下雨」的潮湿预期相矛盾。"}], "explanations": {"阴": "阴指天上有云、不见太阳，与「也许一会儿会下雨」的预期相符，是正确答案。", "热闹": "搭配：「热闹」形容场面喧闹，不能用来描述天空的状态。", "高": "搭配：「高」描写高度，不能用来描述天空的天气状态。", "干燥": "语义：干燥指空气缺水，与「也许会下雨」的潮湿预期相矛盾。"}, "sentence_index": 6, "correct_answer": "阴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这几天天一直阴着，太阳很大。", "explanation": "这里应该用〈晴〉。阴指看不到太阳，与「太阳很大」矛盾。"}, {"text": "中午的阳光很强，天却阴得厉害，我们去游泳吧。", "explanation": "这里应该用〈晴〉。阴指看不到太阳，与「阳光很强」矛盾。"}, {"text": "今天天气很阴，万里无云。", "explanation": "这里应该用〈晴朗〉。阴指天上有云、看不到太阳，与「万里无云」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99077, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "中午以后天阴的下来了，我们早点回家吧。", "corrected_sentence": "中午以后天阴下来了，我们早点回家吧。", "error_description": "错误在于「阴」后多加了助词「的」：「阴」作谓语后直接接补语「下来」，应说「天阴下来了」，不能说「天阴的下来了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99077, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "外面天阴了着，我们别出去了。", "corrected_sentence": "外面天阴着，我们别出去了。", "error_description": "错误在于体标：「阴」后面只能用一个体标，「了」和「着」不能并用；表示持续的状态应说「天阴着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
