INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99081, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "阶是楼梯上一级一级的地方，踩着往上走。", "primary_collocate": null, "pronunciation": "jiē", "ipa": "tɕjɛ˥", "syllable_count": 1, "sentences": [{"text": "房子前面有七阶，不太高。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踩着每一阶往上走。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一阶太滑了，你扶着墙走。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师站在第三阶上，大家都看得见。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼梯很旧，有一阶坏了。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝刚学走路，爬不了两阶。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请别在那一阶上停留，大家要上下楼。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边走一边数，一共走了十二阶。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后一阶比前一阶高一点。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在下面第二阶等你。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "階", "label": "繁体"}, {"form": "台阶", "label": "复合"}, {"form": "阶梯", "label": "复合"}], "register": "中性", "sense_fingerprint": "楼梯上一级一级、可以踩着往上走的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4e257c-d76d-447e-870c-0909fbaadfdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99081, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "阶", "is_correct": true, "explanation": "正确。阶指楼梯上一级一级、可以踩着走的地方。"}, {"text": "解", "is_correct": false, "explanation": "jiě 与 jiē 声调不同，意思是解开或解决。"}, {"text": "借", "is_correct": false, "explanation": "jiè 与 jiē 声调不同，意思是借出或借入。"}, {"text": "节", "is_correct": false, "explanation": "jié 与 jiē 声调不同，意思是节（季节、节日）。"}, {"text": "届", "is_correct": false, "explanation": "jiè 与 jiē 声调不同，意思是届（第一届、届时）。"}], "explanations": {"阶": "正确。阶指楼梯上一级一级、可以踩着走的地方。", "解": "jiě 与 jiē 声调不同，意思是解开或解决。", "借": "jiè 与 jiē 声调不同，意思是借出或借入。", "节": "jié 与 jiē 声调不同，意思是节（季节、节日）。", "届": "jiè 与 jiē 声调不同，意思是届（第一届、届时）。"}, "sentence_index": null, "correct_answer": "阶"}, "level_3": {"options": [{"text": "阶", "is_correct": true, "explanation": "正确。“阶”指楼梯上一级一级的地方，房子前面的台阶可说“七阶”。"}, {"text": "岁", "is_correct": false, "explanation": "语义：“岁”指年龄，房子前面不能用岁数来数。"}, {"text": "元", "is_correct": false, "explanation": "搭配：“元”用于钱，房子不能按元来计。"}, {"text": "天", "is_correct": false, "explanation": "语义：“天”指日子，房子前面不能按天来数。"}], "explanations": {"阶": "正确。“阶”指楼梯上一级一级的地方，房子前面的台阶可说“七阶”。", "岁": "语义：“岁”指年龄，房子前面不能用岁数来数。", "元": "搭配：“元”用于钱，房子不能按元来计。", "天": "语义：“天”指日子，房子前面不能按天来数。"}, "sentence_index": 0, "correct_answer": "阶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家住在第十阶。", "explanation": "这里应该用〈层〉。住在几楼要说“第几层”，“阶”指楼梯上的一级。"}, {"text": "我站在一把阶上。", "explanation": "这里应该用〈级〉。“把”用于有柄的物件，台阶要用“级”来数。"}, {"text": "这场谈判已经进入了最后一阶，双方都很满意。", "explanation": "这里应该用〈阶段〉。说事情的进展要用“阶段”，“阶”在这里指楼梯的一级，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99081, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "阶", "is_correct": true, "explanation": "正确。阶指楼梯上一级一级、可以踩着走的地方。"}, {"text": "姐", "is_correct": false, "explanation": "jiě 与 jiē 声调不同，意思是姐姐。"}, {"text": "介", "is_correct": false, "explanation": "jiè 与 jiē 声调不同，意思是介绍或介于。"}, {"text": "杰", "is_correct": false, "explanation": "jié 与 jiē 声调不同，意思是杰出的人。"}, {"text": "戒", "is_correct": false, "explanation": "jiè 与 jiē 声调不同，意思是戒除或戒指。"}], "explanations": {"阶": "正确。阶指楼梯上一级一级、可以踩着走的地方。", "姐": "jiě 与 jiē 声调不同，意思是姐姐。", "介": "jiè 与 jiē 声调不同，意思是介绍或介于。", "杰": "jié 与 jiē 声调不同，意思是杰出的人。", "戒": "jiè 与 jiē 声调不同，意思是戒除或戒指。"}, "sentence_index": null, "correct_answer": "阶"}, "level_3": {"options": [{"text": "阶", "is_correct": true, "explanation": "正确。“那一阶”指楼梯上的某一级，可以踩着上下楼。"}, {"text": "瓶", "is_correct": false, "explanation": "语义：“瓶”是容器，不能在上面停留，也不能上下楼。"}, {"text": "杯", "is_correct": false, "explanation": "语义：“杯”是容器，不是可以站或停留的地方。"}, {"text": "碗", "is_correct": false, "explanation": "搭配：“在……上停留”不搭配“碗”。"}], "explanations": {"阶": "正确。“那一阶”指楼梯上的某一级，可以踩着上下楼。", "瓶": "语义：“瓶”是容器，不能在上面停留，也不能上下楼。", "杯": "语义：“杯”是容器，不是可以站或停留的地方。", "碗": "搭配：“在……上停留”不搭配“碗”。"}, "sentence_index": 6, "correct_answer": "阶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他爬上一座阶去看风景。", "explanation": "这里应该用〈级〉。“座”用于山、桥、楼等大型物体，台阶不用“座”来数。"}, {"text": "门口有三条阶，你慢点走。", "explanation": "这里应该用〈级〉。“条”用于细长的东西，台阶要用“级”来数。"}, {"text": "我坐在这间阶上等你。", "explanation": "这里应该用〈级〉。“间”用于房屋，台阶要用“级”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99081, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一步一步走进第三阶，停了下来。", "corrected_sentence": "他一步一步走上第三阶，停了下来。", "error_description": "“第三阶”是楼梯上的一级，应说“走上”，不能说“走进”。“走进第三阶”应改为“走上第三阶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他站进第二阶上，看着大家。", "corrected_sentence": "他站在第二阶上，看着大家。", "error_description": "“站”后接处所要用“在”，不能用“进”。“站进第二阶上”应改为“站在第二阶上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
