INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99082, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "台阶；楼梯的一级。", "primary_collocate": null, "pronunciation": "jiē", "ipa": "tɕjɛ˥", "syllable_count": 1, "sentences": [{"text": "这个楼梯一共有三十阶。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一步跨了两阶。", "target_word": "阶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子一阶一阶地往上爬。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门前有五阶，老人走得很慢。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坐在最上面的一阶上等我。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我数了一下，山上的路有三百阶。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，第一阶有点高。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每上一阶，我就停下来休息一下。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁口的楼梯有四十阶，我走累了。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从最下面一阶开始往上数。", "target_word": "阶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "階", "label": "繁体"}, {"form": "台阶", "label": "复合"}, {"form": "阶梯", "label": "复合"}], "register": "中性", "sense_fingerprint": "楼梯或台阶中的一级，可数着说几阶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4e257c-d76d-447e-870c-0909fbaadfdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99082, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "阶", "is_correct": true, "explanation": "正确。阶指楼梯或台阶的一级。"}, {"text": "姐", "is_correct": false, "explanation": "jiě 与 jiē 声调不同，意思是姐姐。"}, {"text": "借", "is_correct": false, "explanation": "jiè 与 jiē 声调不同，意思是借出或借入。"}, {"text": "戒", "is_correct": false, "explanation": "jiè 与 jiē 声调不同，意思是戒除或戒指。"}, {"text": "解", "is_correct": false, "explanation": "jiě 与 jiē 声调不同，意思是解开或解决。"}], "explanations": {"阶": "正确。阶指楼梯或台阶的一级。", "姐": "jiě 与 jiē 声调不同，意思是姐姐。", "借": "jiè 与 jiē 声调不同，意思是借出或借入。", "戒": "jiè 与 jiē 声调不同，意思是戒除或戒指。", "解": "jiě 与 jiē 声调不同，意思是解开或解决。"}, "sentence_index": null, "correct_answer": "阶"}, "level_3": {"options": [{"text": "阶", "is_correct": true, "explanation": "正确。“阶”是楼梯的一级，数台阶可说“三十阶”。"}, {"text": "页", "is_correct": false, "explanation": "语义：“页”用于书本纸张，楼梯不能用页来数。"}, {"text": "岁", "is_correct": false, "explanation": "语义：“岁”只用于年龄，与楼梯无关。"}, {"text": "元", "is_correct": false, "explanation": "搭配：“元”用来计钱，不能用来数楼梯的级数。"}], "explanations": {"阶": "正确。“阶”是楼梯的一级，数台阶可说“三十阶”。", "页": "语义：“页”用于书本纸张，楼梯不能用页来数。", "岁": "语义：“岁”只用于年龄，与楼梯无关。", "元": "搭配：“元”用来计钱，不能用来数楼梯的级数。"}, "sentence_index": 0, "correct_answer": "阶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的新生活终于迈出了第一阶。", "explanation": "这里应该用〈步〉。“阶”在这里指阶段，与楼梯无关；开始做一件事应说“迈出第一步”。"}, {"text": "这两家公司的合作已经进入了第二阶，前景很好。", "explanation": "这里应该用〈阶段〉。说合作的进展要用“阶段”，“阶”指楼梯的一级。"}, {"text": "我数了一下，门前有三只阶。", "explanation": "这里应该用〈级〉。台阶要用“级”来数，“只”用于动物或成对的东西，不能用来数台阶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99082, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "阶", "is_correct": true, "explanation": "正确。阶指楼梯或台阶的一级。"}, {"text": "节", "is_correct": false, "explanation": "jié 与 jiē 声调不同，意思是节（季节、节日）。"}, {"text": "介", "is_correct": false, "explanation": "jiè 与 jiē 声调不同，意思是介绍或介于。"}, {"text": "届", "is_correct": false, "explanation": "jiè 与 jiē 声调不同，意思是届（第一届、届时）。"}, {"text": "杰", "is_correct": false, "explanation": "jié 与 jiē 声调不同，意思是杰出的人。"}], "explanations": {"阶": "正确。阶指楼梯或台阶的一级。", "节": "jié 与 jiē 声调不同，意思是节（季节、节日）。", "介": "jiè 与 jiē 声调不同，意思是介绍或介于。", "届": "jiè 与 jiē 声调不同，意思是届（第一届、届时）。", "杰": "jié 与 jiē 声调不同，意思是杰出的人。"}, "sentence_index": null, "correct_answer": "阶"}, "level_3": {"options": [{"text": "阶", "is_correct": true, "explanation": "正确。“阶”是楼梯的一级，“第一阶”指最下面的那一级。"}, {"text": "名", "is_correct": false, "explanation": "语义：“名”指名次，没有高低，这里说不通。"}, {"text": "课", "is_correct": false, "explanation": "语义：“课”指课程，不能说有点高。"}, {"text": "页", "is_correct": false, "explanation": "搭配：“页”指纸张，不能说有点高。"}], "explanations": {"阶": "正确。“阶”是楼梯的一级，“第一阶”指最下面的那一级。", "名": "语义：“名”指名次，没有高低，这里说不通。", "课": "语义：“课”指课程，不能说有点高。", "页": "搭配：“页”指纸张，不能说有点高。"}, "sentence_index": 6, "correct_answer": "阶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的汉语水平考到了三阶。", "explanation": "这里应该用〈级〉。考试等级一般说“三级”，不说“三阶”。"}, {"text": "这个楼梯有三把阶。", "explanation": "这里应该用〈级〉。“把”用于有柄的物件，台阶要用“级”来数。"}, {"text": "他一口气爬了三条阶。", "explanation": "这里应该用〈级〉。“条”用于细长的东西，台阶要用“级”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每次跨两只阶，走得很稳。", "corrected_sentence": "他每次跨两阶，走得很稳。", "error_description": "数台阶直接用数词加“阶”，不用“只”。“两只阶”应改为“两阶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我坐在第一阶们上等你。", "corrected_sentence": "我坐在第一阶上等你。", "error_description": "“们”只用于人，不能加在“阶”后面。“第一阶们”应改为“第一阶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
