INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99085, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雄性的动物，与雌相对。", "primary_collocate": null, "pronunciation": "xióng", "ipa": "ɕjʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "笼子里有两只猫，一雌一雄。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对鸟一雄一雌，雄的比雌的大。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这群狮子里，是雄是雌一看就知道。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你分得出哪只是雄，哪只是雌吗？", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这三只小狗，两只是雌，一只是雄。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂里，雄的不采蜜。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "养鱼时，一雄配两雌最好。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡群里，雄的总是叫得最响。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孔雀中，雄的尾巴最美。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫长大后，才能看出是雌是雄。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "雄性", "label": "复合"}, {"form": "雌雄", "label": "复合"}], "register": "中性", "sense_fingerprint": "指雄性的动物，与雌相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3997216-d3ae-4dcb-ab5c-3abc7b75bba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99085, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雄", "is_correct": true, "explanation": "雄 xióng（第二声）：指雄性的动物，与雌相对。"}, {"text": "胸", "is_correct": false, "explanation": "胸 xiōng（第一声）与雄 xióng（第二声）声调不同，意思是胸部。"}, {"text": "兄", "is_correct": false, "explanation": "兄 xiōng（第一声）与雄 xióng（第二声）声调不同，意思是哥哥。"}, {"text": "凶", "is_correct": false, "explanation": "凶 xiōng（第一声）与雄 xióng（第二声）声调不同，意思是凶狠。"}], "explanations": {"雄": "雄 xióng（第二声）：指雄性的动物，与雌相对。", "胸": "胸 xiōng（第一声）与雄 xióng（第二声）声调不同，意思是胸部。", "兄": "兄 xiōng（第一声）与雄 xióng（第二声）声调不同，意思是哥哥。", "凶": "凶 xiōng（第一声）与雄 xióng（第二声）声调不同，意思是凶狠。"}, "sentence_index": null, "correct_answer": "雄"}, "level_3": {"options": [{"text": "雄", "is_correct": true, "explanation": "正确：与“一雌”构成雌雄对应，指一只雄猫。"}, {"text": "雌", "is_correct": false, "explanation": "语义：前后都是雌的，无法形成“一雌一雄”的对应。"}, {"text": "狗", "is_correct": false, "explanation": "语义：句子说的是两只猫，插入“狗”与前文矛盾。"}, {"text": "人", "is_correct": false, "explanation": "搭配：雌雄一般指动植物的性别，不用于人。"}], "explanations": {"雄": "正确：与“一雌”构成雌雄对应，指一只雄猫。", "雌": "语义：前后都是雌的，无法形成“一雌一雄”的对应。", "狗": "语义：句子说的是两只猫，插入“狗”与前文矛盾。", "人": "搭配：雌雄一般指动植物的性别，不用于人。"}, "sentence_index": 0, "correct_answer": "雄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司的资金很雄，足以投资新项目。", "explanation": "这里应该用〈雄厚〉。“雄”单用不能形容资金充足，要说“雄厚”。"}, {"text": "他是我们班的雄，大家都很佩服他。", "explanation": "这里应该用〈英雄〉。“雄”单用不指英雄，表示英雄要说“英雄”。"}, {"text": "这块玻璃是雄的，很透明。", "explanation": "“雄”只用于有性别的动物，玻璃没有性别，不能用“雄”来形容它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99085, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "雄", "is_correct": true, "explanation": "雄 xióng（第二声）：指雄性的动物，与雌相对。"}, {"text": "穷", "is_correct": false, "explanation": "穷 qióng 与雄 xióng 声母不同，q 与 x 不同，意思是贫穷。"}, {"text": "形", "is_correct": false, "explanation": "形 xíng 与雄 xióng 韵母不同，-ing 与 -iong 不同，意思是形状。"}, {"text": "行", "is_correct": false, "explanation": "行 xíng 与雄 xióng 韵母不同，-ing 与 -iong 不同，意思是行走。"}, {"text": "型", "is_correct": false, "explanation": "型 xíng 与雄 xióng 韵母不同，-ing 与 -iong 不同，意思是类型。"}], "explanations": {"雄": "雄 xióng（第二声）：指雄性的动物，与雌相对。", "穷": "穷 qióng 与雄 xióng 声母不同，q 与 x 不同，意思是贫穷。", "形": "形 xíng 与雄 xióng 韵母不同，-ing 与 -iong 不同，意思是形状。", "行": "行 xíng 与雄 xióng 韵母不同，-ing 与 -iong 不同，意思是行走。", "型": "型 xíng 与雄 xióng 韵母不同，-ing 与 -iong 不同，意思是类型。"}, "sentence_index": null, "correct_answer": "雄"}, "level_3": {"options": [{"text": "雄", "is_correct": true, "explanation": "正确：养鱼时“一雄配两雌”指一条雄鱼与两条雌鱼配对。"}, {"text": "男", "is_correct": false, "explanation": "搭配：“男”指人，不用于描述养鱼时鱼的配对。"}, {"text": "女", "is_correct": false, "explanation": "搭配：“女”指人，句中讲的是鱼的雌雄配对。"}, {"text": "母", "is_correct": false, "explanation": "语义：“母”指雌性，“一母配两雌”两边都是雌性，无法配对。"}], "explanations": {"雄": "正确：养鱼时“一雄配两雌”指一条雄鱼与两条雌鱼配对。", "男": "搭配：“男”指人，不用于描述养鱼时鱼的配对。", "女": "搭配：“女”指人，句中讲的是鱼的雌雄配对。", "母": "语义：“母”指雌性，“一母配两雌”两边都是雌性，无法配对。"}, "sentence_index": 6, "correct_answer": "雄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑是雄还是雌？", "explanation": "雄、雌只用于有性别的生物，电脑没有性别，不能用来区分。"}, {"text": "这块石头分雄雌吗？", "explanation": "石头没有性别，不能用“雄”“雌”来区分，这里的用法不当。"}, {"text": "他的雄很大，大家都很佩服。", "explanation": "这里的“雄”用作指人的抱负，但单用“雄”不表示抱负，要说“雄心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99085, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你看得出这两只兔子哪只是雄，哪只雌是吗？", "corrected_sentence": "你看得出这两只兔子哪只是雄，哪只是雌吗？", "error_description": "语序错误：“是”应放在“雌”前面，说“哪只是雌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99085, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这对鸽子一雌一的雄，正好配对。", "corrected_sentence": "这对鸽子一雌一雄，正好配对。", "error_description": "多加了“的”：“的”不能插在“一雌一”和“雄”之间，应说“一雌一雄”，不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99086, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "雌", "is_correct": true, "explanation": "雌与雄是反义词，指生物中产生卵子的一性，与此句“雄”的性别义相对。"}, {"text": "快", "is_correct": false, "explanation": "“快”描写速度，与“雄”的生物性别义无关，不构成反义关系。"}, {"text": "软", "is_correct": false, "explanation": "“软”描写质地，与“雄”的生物性别义无关。"}, {"text": "甜", "is_correct": false, "explanation": "“甜”描写味道，与“雄”的生物性别义无关。"}], "correct_answer": "雌", "explanations": {"雌": "雌与雄是反义词，指生物中产生卵子的一性，与此句“雄”的性别义相对。", "快": "“快”描写速度，与“雄”的生物性别义无关，不构成反义关系。", "软": "“软”描写质地，与“雄”的生物性别义无关。", "甜": "“甜”描写味道，与“雄”的生物性别义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
