INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99086, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "生物中能产生精子的，与雌相对。", "primary_collocate": null, "pronunciation": "xióng", "ipa": "ɕjʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "这只小鸡是雄的，那只是雌的。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雄的孔雀会开屏，雌的不会。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条金鱼是雄的还是雌的？", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雄的青蛙叫得很大声。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这只小狗是雄的。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雄的蚊子不咬人，只有雌的咬人。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雄的海马可以生宝宝。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这群鸡里，雄的比雌的大。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雄的和雌的放在一起，才能有小鸟。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸭子里，雄的羽毛更漂亮。", "target_word": "雄", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "雄性", "label": "复合"}, {"form": "雌雄", "label": "复合"}], "register": "中性", "sense_fingerprint": "生物学上的雄性，与雌相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3997216-d3ae-4dcb-ab5c-3abc7b75bba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99086, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雄", "is_correct": true, "explanation": "雄 xióng（第二声）：生物中能产生精子的，与雌相对。"}, {"text": "胸", "is_correct": false, "explanation": "胸 xiōng（第一声）与雄 xióng（第二声）声调不同，意思是胸部。"}, {"text": "兄", "is_correct": false, "explanation": "兄 xiōng（第一声）与雄 xióng（第二声）声调不同，意思是哥哥。"}, {"text": "凶", "is_correct": false, "explanation": "凶 xiōng（第一声）与雄 xióng（第二声）声调不同，意思是凶狠。"}], "explanations": {"雄": "雄 xióng（第二声）：生物中能产生精子的，与雌相对。", "胸": "胸 xiōng（第一声）与雄 xióng（第二声）声调不同，意思是胸部。", "兄": "兄 xiōng（第一声）与雄 xióng（第二声）声调不同，意思是哥哥。", "凶": "凶 xiōng（第一声）与雄 xióng（第二声）声调不同，意思是凶狠。"}, "sentence_index": null, "correct_answer": "雄"}, "level_3": {"options": [{"text": "雄", "is_correct": true, "explanation": "正确：与后句“那只是雌的”相对，说明这只是雄性。"}, {"text": "雌", "is_correct": false, "explanation": "语义：前后两只都是雌的，没有雌雄对比，与“那只是雌的”的对照矛盾。"}, {"text": "大", "is_correct": false, "explanation": "体貌：“大”描写体型，句子要区分的是性别，不能说明雌雄。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”说外貌好看，与句子所要区分的性别无关。"}], "explanations": {"雄": "正确：与后句“那只是雌的”相对，说明这只是雄性。", "雌": "语义：前后两只都是雌的，没有雌雄对比，与“那只是雌的”的对照矛盾。", "大": "体貌：“大”描写体型，句子要区分的是性别，不能说明雌雄。", "漂亮": "体貌：“漂亮”说外貌好看，与句子所要区分的性别无关。"}, "sentence_index": 0, "correct_answer": "雄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我哥哥是雄的，今年二十岁。", "explanation": "这里应该用〈男〉。雄只用于动物、植物的性别，指人的性别要说“男”。"}, {"text": "这把椅子是雄的，很结实。", "explanation": "椅子没有性别，“雄”只用于有性别的生物，这里不能用。"}, {"text": "这个女孩是雄的，今年五岁。", "explanation": "这里应该用〈女的〉。“雄”只指动植物的雄性，不能用来指人，说女孩的性别要用“女的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99086, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "雄", "is_correct": true, "explanation": "雄 xióng（第二声）：生物中能产生精子的，与雌相对。"}, {"text": "穷", "is_correct": false, "explanation": "穷 qióng 与雄 xióng 声母不同，q 与 x 不同，意思是贫穷。"}, {"text": "形", "is_correct": false, "explanation": "形 xíng 与雄 xióng 韵母不同，-ing 与 -iong 不同，意思是形状。"}, {"text": "行", "is_correct": false, "explanation": "行 xíng 与雄 xióng 韵母不同，-ing 与 -iong 不同，意思是行走。"}, {"text": "型", "is_correct": false, "explanation": "型 xíng 与雄 xióng 韵母不同，-ing 与 -iong 不同，意思是类型。"}], "explanations": {"雄": "雄 xióng（第二声）：生物中能产生精子的，与雌相对。", "穷": "穷 qióng 与雄 xióng 声母不同，q 与 x 不同，意思是贫穷。", "形": "形 xíng 与雄 xióng 韵母不同，-ing 与 -iong 不同，意思是形状。", "行": "行 xíng 与雄 xióng 韵母不同，-ing 与 -iong 不同，意思是行走。", "型": "型 xíng 与雄 xióng 韵母不同，-ing 与 -iong 不同，意思是类型。"}, "sentence_index": null, "correct_answer": "雄"}, "level_3": {"options": [{"text": "雄", "is_correct": true, "explanation": "正确：海马中孵育幼崽的是雄性，与“可以生宝宝”相符。"}, {"text": "死", "is_correct": false, "explanation": "语义：死了的海马不能生育，与“可以生宝宝”矛盾。"}, {"text": "空", "is_correct": false, "explanation": "语义：“空”指里面没有东西，无法修饰能生育的动物。"}, {"text": "硬", "is_correct": false, "explanation": "体貌：“硬”描写身体的质地，与能否生育无关，句子不通。"}], "explanations": {"雄": "正确：海马中孵育幼崽的是雄性，与“可以生宝宝”相符。", "死": "语义：死了的海马不能生育，与“可以生宝宝”矛盾。", "空": "语义：“空”指里面没有东西，无法修饰能生育的动物。", "硬": "体貌：“硬”描写身体的质地，与能否生育无关，句子不通。"}, "sentence_index": 6, "correct_answer": "雄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的雄很大，想当总统。", "explanation": "这里应该用〈雄心〉。“雄”单用不表示抱负，表示抱负要说“雄心”。"}, {"text": "他是我们班的雄，大家都很佩服他。", "explanation": "这里应该用〈英雄〉。“雄”单用不指英雄，表示英雄要说“英雄”。"}, {"text": "我们公司的资金很雄，足以投资新项目。", "explanation": "这里应该用〈雄厚〉。“雄”单用不能形容资金充足，要说“雄厚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈说这只小猫是雄地。", "corrected_sentence": "妈妈说这只小猫是雄的。", "error_description": "助词错误：“是……的”结构要用“的”，不能用“地”，应说“是雄的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这群孔雀里，雄地尾巴更长。", "corrected_sentence": "这群孔雀里，雄的尾巴更长。", "error_description": "助词错误：“雄”修饰名词“尾巴”时应用“的”，不能用“地”（“地”用于修饰动词），应说“雄的尾巴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99089, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散：离开集合的地点各自散开，与集结“从各地聚到一处”正相反，两者是反义词。"}, {"text": "休息", "is_correct": false, "explanation": "休息：停止活动以恢复体力，与集结不构成反义关系。"}, {"text": "出发", "is_correct": false, "explanation": "出发：动身前往某地，与集结不是反义词。"}, {"text": "思考", "is_correct": false, "explanation": "思考：用脑子考虑问题，与集结不构成反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "分散：离开集合的地点各自散开，与集结“从各地聚到一处”正相反，两者是反义词。", "休息": "休息：停止活动以恢复体力，与集结不构成反义关系。", "出发": "出发：动身前往某地，与集结不是反义词。", "思考": "思考：用脑子考虑问题，与集结不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99089, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散：各自散开，与集结“聚到一处”正相反，两者是反义词。"}, {"text": "阅读", "is_correct": false, "explanation": "阅读：看文字并理解内容，与集结不构成反义关系。"}, {"text": "生长", "is_correct": false, "explanation": "生长：植物或生物逐渐长大，与集结不构成反义关系。"}, {"text": "收拾", "is_correct": false, "explanation": "收拾：整理、整顿物品，与集结不构成反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "分散：各自散开，与集结“聚到一处”正相反，两者是反义词。", "阅读": "阅读：看文字并理解内容，与集结不构成反义关系。", "生长": "生长：植物或生物逐渐长大，与集结不构成反义关系。", "收拾": "收拾：整理、整顿物品，与集结不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99089, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "集结是很多人从不同地方来，聚到一个地方。", "primary_collocate": null, "pronunciation": "jí jié", "ipa": "tɕi˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "各地的运动员已经集结到北京了。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末，从各地来的志愿者在广场集结。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们早上七点在学校门口集结。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队员们从不同的城市集结到一起。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消防员接到电话后，很快就集结了。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "来自各国的代表集结在这个小镇上，准备开会。", "target_word": "集结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家请在门口集结，我们马上出发。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了开会，各部门的人都集结到了这里。", "target_word": "集结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好几百名工人从四面八方集结过来。", "target_word": "集结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛的人在体育馆前集结完毕。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "集结了", "label": "体标（了）"}, {"form": "集结着", "label": "体标（着）"}, {"form": "集结过", "label": "体标（过）"}, {"form": "集結", "label": "繁体"}], "register": "书面", "sense_fingerprint": "很多人从各地来，聚到同一个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf938f4-42ad-492e-99ec-250d2cb0e12e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99089, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集结", "is_correct": true, "explanation": "集结：很多人从各地会合到同一处，与句中“各地”“到北京”相合。"}, {"text": "撤退", "is_correct": false, "explanation": "语义：撤退指部队从前线后撤，与“运动员已经到北京”这种会合语境不符，运动员也不会撤退。"}, {"text": "寄", "is_correct": false, "explanation": "搭配：“寄”的对象是信件、包裹等物品，不能用于运动员。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、地面等，运动员不能“打扫到北京”。"}], "explanations": {"集结": "集结：很多人从各地会合到同一处，与句中“各地”“到北京”相合。", "撤退": "语义：撤退指部队从前线后撤，与“运动员已经到北京”这种会合语境不符，运动员也不会撤退。", "寄": "搭配：“寄”的对象是信件、包裹等物品，不能用于运动员。", "打扫": "搭配：“打扫”的对象是房间、地面等，运动员不能“打扫到北京”。"}, "sentence_index": 0, "correct_answer": "集结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下雨了，很多人集结到了车站的屋檐下。", "explanation": "这里应该用〈聚集〉。集结指为某项行动有组织地会合，躲雨的人群是临时聚拢，要用聚集。"}, {"text": "这份报告集结了各地的数据。", "explanation": "这里应该用〈汇集〉。集结只用于人员或兵力，数据、资料要说汇集。"}, {"text": "他把全部精力集结到了考试上。", "explanation": "这里应该用〈集中〉。集结是人或兵力的会合，精力只能说集中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99089, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集结", "is_correct": true, "explanation": "集结：有组织地会合待命，与“大家请在门口”“我们马上出发”相合。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：门口不是水域，“游泳”不能用于在门口进行。"}, {"text": "散开", "is_correct": false, "explanation": "语义：散开指各自分散离去，与“我们马上出发”需要大家聚在一起相矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：在门口睡觉与“马上出发”的要求不相容。"}], "explanations": {"集结": "集结：有组织地会合待命，与“大家请在门口”“我们马上出发”相合。", "游泳": "搭配：门口不是水域，“游泳”不能用于在门口进行。", "散开": "语义：散开指各自分散离去，与“我们马上出发”需要大家聚在一起相矛盾。", "睡觉": "语义：在门口睡觉与“马上出发”的要求不相容。"}, "sentence_index": 6, "correct_answer": "集结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春节那天，一家人在老家集结。", "explanation": "这里应该用〈团聚〉。集结是为行动而会合，家人团圆要说团聚。"}, {"text": "他一个人在书房集结，准备期末考试。", "explanation": "这里应该用〈学习〉。集结指许多人或兵力会合，一个人独自在书房读书要说学习。"}, {"text": "大家在窗口集结买票。", "explanation": "这里应该用〈排队〉。排队是依次等候，集结是多人向一处会合，不能表示依次排列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99089, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防员接到通知后，很快就集结好着。", "corrected_sentence": "消防员接到通知后，很快就集结好了。", "error_description": "错误在体标：“很快就”表示动作已经完成，应用“了”（集结好了）；“着”表示持续的状态，与“很快就”的完成义不合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99089, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们请在校门口集结了，马上出发。", "corrected_sentence": "同学们请在校门口集结，马上出发。", "error_description": "错误在“了”：要求、命令句里“集结”后不能加“了”，“了”表示已经完成，与“请……马上出发”的语气矛盾，应说“请……集结”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99090, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散：离开集合的地点各自散开，与集结正相反，两者是反义词。"}, {"text": "巡逻", "is_correct": false, "explanation": "巡逻：在某个区域来回查看，与集结不构成反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "观看：用眼睛注视，与集结不构成反义关系。"}, {"text": "咳嗽", "is_correct": false, "explanation": "咳嗽：呼吸道受刺激而发出的动作，与集结不构成反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "分散：离开集合的地点各自散开，与集结正相反，两者是反义词。", "巡逻": "巡逻：在某个区域来回查看，与集结不构成反义关系。", "观看": "观看：用眼睛注视，与集结不构成反义关系。", "咳嗽": "咳嗽：呼吸道受刺激而发出的动作，与集结不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99090, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散：离开集合的地点各自散开，与集结正相反，两者是反义词。"}, {"text": "烹饪", "is_correct": false, "explanation": "烹饪：加工食物做成熟食，与集结不构成反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：随意地慢慢走动，与集结不构成反义关系。"}, {"text": "生长", "is_correct": false, "explanation": "生长：生物逐渐长大，与集结不构成反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "分散：离开集合的地点各自散开，与集结正相反，两者是反义词。", "烹饪": "烹饪：加工食物做成熟食，与集结不构成反义关系。", "散步": "散步：随意地慢慢走动，与集结不构成反义关系。", "生长": "生长：生物逐渐长大，与集结不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99090, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "聚集到一处。", "primary_collocate": null, "pronunciation": "jí jié", "ipa": "tɕi˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "军队正在边境集结。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部队已经在河边集结完毕。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天一亮，士兵们就在山下集结了。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敌人把大批人马集结在城外。", "target_word": "集结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船队集结在港口，等着出发。", "target_word": "集结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在广场周围集结了几百人。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "将军下令，所有的部队马上集结。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "救援队集结在村口，准备进山。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在天黑以前集结好了。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大批卡车集结到了城南的空地上。", "target_word": "集结", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "集结了", "label": "体标（了）"}, {"form": "集结着", "label": "体标（着）"}, {"form": "集结过", "label": "体标（过）"}, {"form": "集結", "label": "繁体"}], "register": "书面", "sense_fingerprint": "部队、队伍等聚集到一处待命", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf938f4-42ad-492e-99ec-250d2cb0e12e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99090, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集结", "is_correct": true, "explanation": "集结：部队或队伍聚到一处待命，与“军队”“边境”相合。"}, {"text": "派遣", "is_correct": false, "explanation": "配价：“派遣”需要派出的对象（派遣某人或某部队），句中缺少宾语。"}, {"text": "寄", "is_correct": false, "explanation": "搭配：“寄”的对象是信件、包裹等物品，军队不能作“寄”的主语。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：失踪指人或物下落不明，不能描述军队有计划的部署。"}], "explanations": {"集结": "集结：部队或队伍聚到一处待命，与“军队”“边境”相合。", "派遣": "配价：“派遣”需要派出的对象（派遣某人或某部队），句中缺少宾语。", "寄": "搭配：“寄”的对象是信件、包裹等物品，军队不能作“寄”的主语。", "失踪": "语义：失踪指人或物下落不明，不能描述军队有计划的部署。"}, "sentence_index": 0, "correct_answer": "集结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我一个人在公园集结，准备跑步。", "explanation": "这里应该用〈锻炼〉。集结指许多人或兵力为行动而会合，一个人独自在公园跑步要说锻炼。"}, {"text": "他利用周末集结了很多邮票。", "explanation": "这里应该用〈收集〉。集结用于人员或兵力，邮票这类物品要说收集。"}, {"text": "中秋节全家人集结在一起吃饭。", "explanation": "这里应该用〈团聚〉。集结是为行动而会合，全家吃团圆饭要说团聚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集结", "is_correct": true, "explanation": "集结：有组织地会合待命，与“将军下令”“马上”的行动要求相合。"}, {"text": "借", "is_correct": false, "explanation": "配价：“借”需要借的对象，句中“马上借”后面没有宾语。"}, {"text": "下雨", "is_correct": false, "explanation": "配价：“下雨”是自然现象，不能以“部队”作主语。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：毕业指学生完成学业，部队不能“马上毕业”。"}], "explanations": {"集结": "集结：有组织地会合待命，与“将军下令”“马上”的行动要求相合。", "借": "配价：“借”需要借的对象，句中“马上借”后面没有宾语。", "下雨": "配价：“下雨”是自然现象，不能以“部队”作主语。", "毕业": "语义：毕业指学生完成学业，部队不能“马上毕业”。"}, "sentence_index": 6, "correct_answer": "集结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他和女朋友约好在公园集结。", "explanation": "这里应该用〈会面〉。集结要求许多人或兵力会合，两个人见面要说会面。"}, {"text": "他把注意力集结在书上。", "explanation": "这里应该用〈集中〉。集结用于人员或兵力的会合，注意力只能说集中。"}, {"text": "他们在食堂门口集结打饭。", "explanation": "这里应该用〈排队〉。排队是依次等候，集结是多人向一处会合，不能表示依次排列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "部队正在边境集结了。", "corrected_sentence": "部队正在边境集结着。", "error_description": "错误在体标：“正在”表示动作进行中，应与“着”搭配（集结着）；“了”表示动作完成，不能与“正在”同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "救援车辆在村口集结的。", "corrected_sentence": "救援车辆在村口集结了。", "error_description": "错误在助词：动作完成应用“了”，句末误用“的”，“集结的”不能独立成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
