INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99093, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "双眼是两只眼睛。", "primary_collocate": null, "pronunciation": "shuāng yǎn", "ipa": "ʂwaŋ˥ jɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的双眼很大，也很亮。", "target_word": "双眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闭上双眼，轻轻睡着了。", "target_word": "双眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请睁开你的双眼看一看。", "target_word": "双眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用双眼看着窗外的雪。", "target_word": "双眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看书太久，我的双眼很累。", "target_word": "双眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他双眼看不见，但是心很亮。", "target_word": "双眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的双眼里都是笑。", "target_word": "双眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了他的双眼。", "target_word": "双眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭了很久，双眼都红了。", "target_word": "双眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫的双眼像两颗绿宝石。", "target_word": "双眼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "人或动物的两只眼睛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b12da1c0-45be-4ff5-b000-71e282348403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99093, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耳朵", "is_correct": false, "explanation": "搭配：“亮”不能用来形容耳朵，与句中的“也很亮”不搭。"}, {"text": "双眼", "is_correct": true, "explanation": "正确：“双眼”指两只眼睛，既可以很大，也可以很亮，符合句意。"}, {"text": "鼻子", "is_correct": false, "explanation": "搭配：“很亮”一般不用来形容鼻子，与句中描写的特征不搭。"}, {"text": "手指", "is_correct": false, "explanation": "语义：手指很大、很亮不符合常理，与句中描写的人物特征不搭。"}], "explanations": {"耳朵": "搭配：“亮”不能用来形容耳朵，与句中的“也很亮”不搭。", "双眼": "正确：“双眼”指两只眼睛，既可以很大，也可以很亮，符合句意。", "鼻子": "搭配：“很亮”一般不用来形容鼻子，与句中描写的特征不搭。", "手指": "语义：手指很大、很亮不符合常理，与句中描写的人物特征不搭。"}, "sentence_index": 0, "correct_answer": "双眼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她戴上双眼看书。", "explanation": "这里应该用〈眼镜〉。戴的是眼镜，双眼是器官，不能戴上。"}, {"text": "她的双眼又黑又粗，很有个性。", "explanation": "这里应该用〈眉毛〉。眉毛可以又黑又粗，双眼是两只眼睛，不能用“粗”来形容。"}, {"text": "她的双眼断了，正在打石膏。", "explanation": "这里应该用〈胳膊〉。胳膊可以骨折、断掉，双眼不能断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99093, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头里不会充满笑，“石头里都是笑”说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是可以装满笑的地方，与“里都是笑”的语境不符。"}, {"text": "铅笔", "is_correct": false, "explanation": "搭配：“里都是笑”要求空间或容器，“铅笔”不能这样搭配。"}, {"text": "双眼", "is_correct": true, "explanation": "正确：眼睛里充满笑意是常见的描写，“双眼里都是笑”符合句意。"}], "explanations": {"石头": "语义：石头里不会充满笑，“石头里都是笑”说不通。", "冰箱": "语义：冰箱不是可以装满笑的地方，与“里都是笑”的语境不符。", "铅笔": "搭配：“里都是笑”要求空间或容器，“铅笔”不能这样搭配。", "双眼": "正确：眼睛里充满笑意是常见的描写，“双眼里都是笑”符合句意。"}, "sentence_index": 6, "correct_answer": "双眼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用双眼听音乐。", "explanation": "这里应该用〈耳朵〉。听声音用耳朵，双眼只用于看东西。"}, {"text": "她的双眼流了下来。", "explanation": "这里应该用〈眼泪〉。流下来的是眼泪，双眼是器官，不能流。"}, {"text": "他用双眼闻花香。", "explanation": "这里应该用〈鼻子〉。闻气味要用鼻子，双眼只用于看东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99093, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他闭上双眼睛，安静地听音乐。", "corrected_sentence": "他闭上双眼，安静地听音乐。", "error_description": "错误：“双眼睛”；正确：“双眼”。“双眼”已经表示两只眼睛，后面不能再加“睛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99093, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把两只双眼揉红了。", "corrected_sentence": "她把双眼揉红了。", "error_description": "数量错误：“双眼”本身已经表示两只眼睛，前面不应再加“两只”；正确应为“她把双眼揉红了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
