INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99097, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电话网是把很多电话连在一起，让大家能打通的线路。", "primary_collocate": null, "pronunciation": "diàn huà wǎng", "ipa": "tjɛn˥˩ xwa˥˩ waŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这个小镇的电话网还不太好。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，全城的电话网都坏了。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在修电话网。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子终于接上了电话网。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话网把很多家庭连在一起。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为电话网太忙，我一直打不通。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想建一个新的电话网。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，电话网很快就恢复了。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，电话网让人们联系更方便。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里没有电话网，我们只能写信。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "电话网络", "label": "复合"}, {"form": "移动电话网", "label": "复合"}], "register": "中性", "sense_fingerprint": "把很多电话连在一起、让大家能打通的线路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b12da1c0-45be-4ff5-b000-71e282348403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99097, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首都", "is_correct": false, "explanation": "语义：首都是国家的政治中心，与句中的“小镇”矛盾，“小镇的首都”说不通。"}, {"text": "电话网", "is_correct": true, "explanation": "正确：电话网指小镇的电话线路系统，“还不太好”正好描述它的状况。"}, {"text": "大城市", "is_correct": false, "explanation": "语义：大城市与“小镇”矛盾，“小镇的大城市”自相矛盾。"}, {"text": "大都市", "is_correct": false, "explanation": "语义：大都市与“小镇”矛盾，“小镇的大都市”自相矛盾。"}], "explanations": {"首都": "语义：首都是国家的政治中心，与句中的“小镇”矛盾，“小镇的首都”说不通。", "电话网": "正确：电话网指小镇的电话线路系统，“还不太好”正好描述它的状况。", "大城市": "语义：大城市与“小镇”矛盾，“小镇的大城市”自相矛盾。", "大都市": "语义：大都市与“小镇”矛盾，“小镇的大都市”自相矛盾。"}, "sentence_index": 0, "correct_answer": "电话网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厨房的墙上挂着电话网。", "explanation": "这里应该用〈电话机〉。电话机是挂在墙上或放在桌上的设备，电话网是线路系统，不能挂在墙上。"}, {"text": "他忘了朋友的电话网。", "explanation": "这里应该用〈号码〉。号码是一串数字，可以忘记；电话网是线路系统，不能说忘记。"}, {"text": "我们的电话网很清楚。", "explanation": "这里应该用〈通话〉。通话的声音可以说清楚，电话网指线路系统，不用“清楚”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99097, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老人", "is_correct": false, "explanation": "搭配：“建”不搭配人，“一个新的老人”本身也自相矛盾。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能由公司建造，“建一个新的月亮”说不通。"}, {"text": "电话网", "is_correct": true, "explanation": "正确：公司建的是新的电话网络系统，与“建一个新的”搭配自然。"}, {"text": "国家", "is_correct": false, "explanation": "语义：公司不能建立国家，与句中的主语“公司”矛盾。"}], "explanations": {"老人": "搭配：“建”不搭配人，“一个新的老人”本身也自相矛盾。", "月亮": "语义：月亮不能由公司建造，“建一个新的月亮”说不通。", "电话网": "正确：公司建的是新的电话网络系统，与“建一个新的”搭配自然。", "国家": "语义：公司不能建立国家，与句中的主语“公司”矛盾。"}, "sentence_index": 6, "correct_answer": "电话网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的电话网屏幕碎了，正在修理。", "explanation": "这里应该用〈手机〉。手机有屏幕，可以碎；电话网是线路系统，没有屏幕。"}, {"text": "我每天晚上都收听电话网的新闻。", "explanation": "这里应该用〈电台〉。电台播送新闻，电话网只是线路系统，不能用来收听新闻。"}, {"text": "电话网的遥控器找不到了。", "explanation": "这里应该用〈电视〉。遥控器是用来操作电视等设备的，电话网没有遥控器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99097, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条街终于接收了电话网。", "corrected_sentence": "这条街终于接通了电话网。", "error_description": "动词错误：“接收”指收到东西或信息，电话网是线路系统，不能被接收；此处应说“接通”，表示线路连通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99097, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区去年终于把这本电话网升级了。", "corrected_sentence": "社区去年终于把这套电话网升级了。", "error_description": "量词错误：“电话网”是成套的系统，应用“套”；“本”用于书册，不能用来计量电话网。正确：“这套电话网”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
