INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99098, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由线路和交换设备组成的、实现电话通话的通信网络。", "primary_collocate": null, "pronunciation": "diàn huà wǎng", "ipa": "tjɛn˥˩ xwa˥˩ waŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "电话网由线路和交换设备组成。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的电话网已经使用了二十年。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在检查电话网的设备。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话网出了问题，用户无法通话。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司负责管理全国的电话网。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的电话网可以同时接通很多电话。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话网中的交换设备很重要。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学习了电话网是怎么工作的。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在维护电话网的部门工作。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话网升级后，通话声音更清楚了。", "target_word": "电话网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "电话网络", "label": "复合"}, {"form": "移动电话网", "label": "复合"}], "register": "中性", "sense_fingerprint": "由线路和交换设备组成、实现电话通话的通信网络", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b12da1c0-45be-4ff5-b000-71e282348403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99098, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "语义：花园由花草树木组成，不是由线路和交换设备组成，与句意不符。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不是由线路和交换设备组成的，与句意不符。"}, {"text": "电话网", "is_correct": true, "explanation": "正确：电话网就是由线路和交换设备组成、实现通话的通信网络，句子的主语正是它。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不可能由线路和交换设备组成。"}], "explanations": {"花园": "语义：花园由花草树木组成，不是由线路和交换设备组成，与句意不符。", "学校": "语义：学校不是由线路和交换设备组成的，与句意不符。", "电话网": "正确：电话网就是由线路和交换设备组成、实现通话的通信网络，句子的主语正是它。", "蛋糕": "语义：蛋糕是食物，不可能由线路和交换设备组成。"}, "sentence_index": 0, "correct_answer": "电话网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的电话网键盘坏了，正在修理。", "explanation": "这里应该用〈电脑〉。电脑有键盘，电话网是线路系统，没有键盘。"}, {"text": "电话网的门关上了，我们下楼。", "explanation": "这里应该用〈电梯〉。电梯有门，电话网是线路系统，没有门。"}, {"text": "电话网的话筒坏了，听不清。", "explanation": "这里应该用〈电话机〉。话筒是电话机的部件，电话网是线路系统，没有话筒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99098, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房里不会有交换设备，“厨房中的交换设备”与句意不符。"}, {"text": "电话网", "is_correct": true, "explanation": "正确：电话网中的交换设备是它的组成部分，句子说的正是这个系统。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋与交换设备无关，“海洋中的交换设备”说不通。"}, {"text": "宠物", "is_correct": false, "explanation": "搭配：“宠物”不能与“中的交换设备”搭配，句中的交换设备不属于宠物。"}], "explanations": {"厨房": "语义：厨房里不会有交换设备，“厨房中的交换设备”与句意不符。", "电话网": "正确：电话网中的交换设备是它的组成部分，句子说的正是这个系统。", "海洋": "语义：海洋与交换设备无关，“海洋中的交换设备”说不通。", "宠物": "搭配：“宠物”不能与“中的交换设备”搭配，句中的交换设备不属于宠物。"}, "sentence_index": 6, "correct_answer": "电话网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的电话网充电很快。", "explanation": "这里应该用〈手机〉。手机需要充电，电话网是线路系统，不能说充电。"}, {"text": "快递员把电话网送到了门口。", "explanation": "这里应该用〈包裹〉。包裹可以被送到门口，电话网是线路系统，不能被送。"}, {"text": "客厅的电话网节目很好看。", "explanation": "这里应该用〈电视〉。电视播放节目，电话网不播放节目，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电话网去年升级过一次。", "corrected_sentence": "这套电话网去年升级过一次。", "error_description": "量词错误：“台”用于机器、设备，电话网是由线路和设备组成的系统，应用“套”，不能用“台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电话网终于修了好。", "corrected_sentence": "电话网终于修好了。", "error_description": "补语错误：“修好”是结果补语，“好”应紧跟在“修”后面，不能说“修了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
