INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99105, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "高等教育是中学读完以后，到大学里继续学习。", "primary_collocate": null, "pronunciation": "gāo děng jiào yù", "ipa": "kaʊ̯˥ təŋ˨˩ tɕjaʊ̯˥˩ y˥˩", "syllable_count": 4, "sentences": [{"text": "她很重视高等教育。", "target_word": "高等教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高等教育让我认识了很多朋友。", "target_word": "高等教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，接受高等教育的人越来越多。", "target_word": "高等教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高等教育一般在大学里进行。", "target_word": "高等教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去国外接受高等教育。", "target_word": "高等教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读完中学以后，他选择接受高等教育。", "target_word": "高等教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母希望孩子能接受高等教育。", "target_word": "高等教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高等教育的学费不便宜。", "target_word": "高等教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有很多高等教育机构。", "target_word": "高等教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有接受过高等教育，他找工作不容易。", "target_word": "高等教育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "中学毕业后在大学里继续学习的教育", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34a82c9e-092e-40ce-a3d1-76b4efb5b7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99105, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高等教育", "is_correct": true, "explanation": "高等教育指中学之后在大学里的学习，可以作「重视」的对象，与句意相符，是正确答案。"}, {"text": "漂亮", "is_correct": false, "explanation": "语法：「重视」后面要接名词性的对象，「漂亮」是形容词，「很重视漂亮」不能说。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：「昨天」表示时间，不能作「重视」的对象。"}, {"text": "非常", "is_correct": false, "explanation": "语法：「非常」是副词，不能放在「重视」后面作宾语。"}], "explanations": {"高等教育": "高等教育指中学之后在大学里的学习，可以作「重视」的对象，与句意相符，是正确答案。", "漂亮": "语法：「重视」后面要接名词性的对象，「漂亮」是形容词，「很重视漂亮」不能说。", "昨天": "语义：「昨天」表示时间，不能作「重视」的对象。", "非常": "语法：「非常」是副词，不能放在「重视」后面作宾语。"}, "sentence_index": 0, "correct_answer": "高等教育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校主要提供高等教育，学生大多是六到十二岁的孩子。", "explanation": "这里应该用〈初等教育〉。高等教育指中学之后的大学阶段，六到十二岁的孩子应接受初等教育。"}, {"text": "他在一所中学工作，主要负责高等教育。", "explanation": "这里应该用〈中学教育〉。高等教育指大学阶段的教育，中学里负责的是中学教育。"}, {"text": "高等教育包括初中和高中。", "explanation": "这里应该用〈中等教育〉。高等教育指中学之后的大学阶段，初中和高中属于中等教育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99105, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高等教育", "is_correct": true, "explanation": "高等教育是父母希望孩子接受的大学阶段教育，与「接受」搭配，是正确答案。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：「接受」接的是教育、治疗、批评等，「早餐」不这样搭配。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，不能作为「接受」的对象。"}, {"text": "公交车", "is_correct": false, "explanation": "语义：公交车是交通工具，不能作为「接受」的对象。"}], "explanations": {"高等教育": "高等教育是父母希望孩子接受的大学阶段教育，与「接受」搭配，是正确答案。", "早餐": "搭配：「接受」接的是教育、治疗、批评等，「早餐」不这样搭配。", "花园": "语义：花园是场所，不能作为「接受」的对象。", "公交车": "语义：公交车是交通工具，不能作为「接受」的对象。"}, "sentence_index": 6, "correct_answer": "高等教育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家托儿所主要进行高等教育，孩子们每天唱歌跳舞。", "explanation": "这里应该用〈学前教育〉。高等教育指大学阶段，托儿所里进行的是学前教育。"}, {"text": "父母在家里对孩子进行高等教育。", "explanation": "这里应该用〈家庭教育〉。高等教育指大学阶段的教育，父母在家里进行的是家庭教育。"}, {"text": "这所特殊学校主要进行高等教育，学生都有听力障碍。", "explanation": "这里应该用〈特殊教育〉。高等教育指大学阶段的教育，有听力障碍的学生应接受特殊教育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99105, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想接受一本更好的高等教育。", "corrected_sentence": "他想接受一种更好的高等教育。", "error_description": "错误在于量词：「高等教育」应用「种」计量，「本」只用于书籍，不能用来计量这个抽象概念。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99105, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想接受一座更好的高等教育。", "corrected_sentence": "他想接受一种更好的高等教育。", "error_description": "错误在于量词：「高等教育」应用「种」计量，「座」用于建筑、山等有体积的事物，不能用于这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d1c1ed8-c4bf-4403-8c42-d08fc5690249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
