INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99109, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鲜花是刚开的、好看又香的花。", "primary_collocate": null, "pronunciation": "xiān huā", "ipa": "ɕjɛn˥ xua˥", "syllable_count": 2, "sentences": [{"text": "阳台上的鲜花开得又香又好看。", "target_word": "鲜花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个周末都去市场买鲜花。", "target_word": "鲜花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的花瓶里插着几朵鲜花。", "target_word": "鲜花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出结束后，观众把鲜花送给歌手。", "target_word": "鲜花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在朋友的婚礼上送一大捧鲜花。", "target_word": "鲜花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹喜欢在头发上戴鲜花。", "target_word": "鲜花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上到处是黄色的鲜花。", "target_word": "鲜花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些鲜花是今天早上刚摘的。", "target_word": "鲜花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了一夜雨，院子里的鲜花更红了。", "target_word": "鲜花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们手里拿着鲜花，等着欢迎客人。", "target_word": "鲜花", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一束鲜花", "label": "量词"}, {"form": "一捧鲜花", "label": "量词"}, {"form": "鮮花", "label": "繁体"}, {"form": "鲜花饼", "label": "复合"}], "register": "中性", "sense_fingerprint": "刚开的、好看又香的花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3efd60c-e060-4786-8479-6c763e1a6952') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99109, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鲜花", "is_correct": true, "explanation": "鲜花（xiān huā）：刚开的、好看又香的花，即正确答案。"}, {"text": "闲话", "is_correct": false, "explanation": "xián（第二声）与 xiān 声调不同，huà（第四声）与 huā（第一声）声调也不同，意思是闲谈。"}, {"text": "仙话", "is_correct": false, "explanation": "xiān（第一声）与 xiān 同音，huà（第四声）与 huā（第一声）声调不同，意思是神仙的故事。"}, {"text": "县花", "is_correct": false, "explanation": "xiàn（第四声）与 xiān（第一声）声调不同，huā 相同，意思是一县选定的代表花。"}], "explanations": {"鲜花": "鲜花（xiān huā）：刚开的、好看又香的花，即正确答案。", "闲话": "xián（第二声）与 xiān 声调不同，huà（第四声）与 huā（第一声）声调也不同，意思是闲谈。", "仙话": "xiān（第一声）与 xiān 同音，huà（第四声）与 huā（第一声）声调不同，意思是神仙的故事。", "县花": "xiàn（第四声）与 xiān（第一声）声调不同，huā 相同，意思是一县选定的代表花。"}, "sentence_index": null, "correct_answer": "鲜花"}, "level_3": {"options": [{"text": "鲜花", "is_correct": true, "explanation": "鲜花：刚开的好看又香的花，与“开得又香又好看”搭配，正确。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶不会“开”花，与“开得又香又好看”的描述不相合。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不会开放，与“开得又香又好看”的描述不符。"}, {"text": "果子", "is_correct": false, "explanation": "搭配：“开”一般配花，果子应说“结”，不说“开得”。"}], "explanations": {"鲜花": "鲜花：刚开的好看又香的花，与“开得又香又好看”搭配，正确。", "树叶": "语义：树叶不会“开”花，与“开得又香又好看”的描述不相合。", "玩具": "语义：玩具不会开放，与“开得又香又好看”的描述不符。", "果子": "搭配：“开”一般配花，果子应说“结”，不说“开得”。"}, "sentence_index": 0, "correct_answer": "鲜花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一颗鲜花。", "explanation": "这里应该用量词〈束〉或〈朵〉。“颗”用于颗粒状的小东西，不用于鲜花。"}, {"text": "桌上放着一头鲜花。", "explanation": "这里应该用量词〈束〉或〈朵〉。“头”用于牛、猪等牲畜，不用于鲜花。"}, {"text": "她送了我一条鲜花。", "explanation": "这里应该用量词〈束〉或〈朵〉。“条”用于细长的东西，不用于鲜花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99109, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鲜花", "is_correct": true, "explanation": "鲜花：开在山坡上的新鲜花朵，与“到处是黄色的”搭配，正确。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：山坡上不会到处是黄色的汽车，与语境不符。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“到处是”说的是能散布各处的东西，教室是固定场所，不能说“到处是”。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机不会出现在山坡上到处都是的情形，与句意不符。"}], "explanations": {"鲜花": "鲜花：开在山坡上的新鲜花朵，与“到处是黄色的”搭配，正确。", "汽车": "语义：山坡上不会到处是黄色的汽车，与语境不符。", "教室": "搭配：“到处是”说的是能散布各处的东西，教室是固定场所，不能说“到处是”。", "洗衣机": "语义：洗衣机不会出现在山坡上到处都是的情形，与句意不符。"}, "sentence_index": 6, "correct_answer": "鲜花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把一尊鲜花放在桌上。", "explanation": "这里应该用量词〈束〉或〈朵〉。“尊”用于神像、雕像等，不用于鲜花。"}, {"text": "窗台上摆着一节鲜花。", "explanation": "这里应该用量词〈束〉或〈朵〉。“节”用于有节的东西，如甘蔗、车厢，不用于鲜花。"}, {"text": "他手里抱着一本鲜花。", "explanation": "这里应该用量词〈束〉或〈朵〉。“本”用于书籍，不用于鲜花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在街边的小摊上买了一个鲜花。", "corrected_sentence": "我在街边的小摊上买了一束鲜花。", "error_description": "量词错误：“鲜花”一般用“束”或“朵”，不用“个”。应写作“一束鲜花”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "节日的广场上摆满了一鲜花。", "corrected_sentence": "节日的广场上摆满了鲜花。", "error_description": "「鲜花」前用了数词「一」却没有量词，而且「摆满了」后面应直接用名词。应去掉「一」，写作「摆满了鲜花」。数词加量词要在别的句子里用，如「买了一束鲜花」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
