INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99113, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一家人是住在一起的爸爸妈妈和孩子们。", "primary_collocate": null, "pronunciation": "yì jiā rén", "ipa": "i˥˩ tɕja˥ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "我们一家人住在一个小房子里。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，一家人一起去公园玩。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家人坐在桌子旁吃晚饭。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一家人都很喜欢小狗。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节那天，一家人在家包饺子。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家人开车去海边了。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一家人每天晚上一起看电视。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家人围着桌子，笑着说话。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和爸爸妈妈、弟弟是一家人。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年了，一家人都回到了老家。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一家子", "label": "口语变体"}], "register": "中性", "sense_fingerprint": "名词：住在一起生活的父母和孩子，一个家庭的全体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc1bb5e-b14c-41de-8ff0-76ccf8bb8da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99113, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一家人", "is_correct": true, "explanation": "正确：“一家人”指住在一起的家庭，与“住在一个小房子里”相符。"}, {"text": "一个人", "is_correct": false, "explanation": "搭配：“我们”是复数，不能和“一个人”搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“住”的主语必须是有生命的人，桌子不能住在房子里。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司是机构，不能“住在”小房子里。"}], "explanations": {"一家人": "正确：“一家人”指住在一起的家庭，与“住在一个小房子里”相符。", "一个人": "搭配：“我们”是复数，不能和“一个人”搭配。", "桌子": "语义：“住”的主语必须是有生命的人，桌子不能住在房子里。", "公司": "语义：公司是机构，不能“住在”小房子里。"}, "sentence_index": 0, "correct_answer": "一家人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班一家人都很努力。", "explanation": "这里应该用〈同学〉。“一家人”指同一家庭的成员，不能指同班的同学。"}, {"text": "我买了一家人。", "explanation": "这里不能用〈一家人〉作“买”的对象，因为它指人；买的对象应是物品或店铺，应改用〈一家店〉这类词。"}, {"text": "三个一家人走进了教室。", "explanation": "量词：这里应该用〈三家人〉。数家庭要用量词“家”，不用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一家人", "is_correct": true, "explanation": "正确：“一家人”指住在一起的家庭成员，与“每天晚上一起看电视”相符。"}, {"text": "电视", "is_correct": false, "explanation": "语义：“电视”是被看的东西，不能作“看电视”的主体。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能“一起看电视”。"}, {"text": "饭桌", "is_correct": false, "explanation": "语义：饭桌是家具，不能“看电视”。"}], "explanations": {"一家人": "正确：“一家人”指住在一起的家庭成员，与“每天晚上一起看电视”相符。", "电视": "语义：“电视”是被看的东西，不能作“看电视”的主体。", "窗户": "语义：窗户不能“一起看电视”。", "饭桌": "语义：饭桌是家具，不能“看电视”。"}, "sentence_index": 6, "correct_answer": "一家人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "很多一家人都回到了老家。", "explanation": "这里应该用〈家庭〉。“一家人”指一个家庭，前面不能用“很多”修饰；表示许多家庭应说“很多家庭”。"}, {"text": "他一个人住，却说一家人都在身边。", "explanation": "语义：“一家人”指同住的家庭成员，一个人独居时不能说“一家人都在身边”，前后矛盾。"}, {"text": "我们学校一家人都参加了运动会。", "explanation": "这里应该用〈师生〉。“一家人”指同一家庭的成员，不能指同一学校的老师和学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一家人们都在家吃晚饭。", "corrected_sentence": "我们一家人都在家吃晚饭。", "error_description": "重复：“一家人”已含“人”，后面不能再加“们”，应说“我们一家人”，去掉多余的“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个周末，他们一个一家人在家休息。", "corrected_sentence": "这个周末，他们一家人在家休息。", "error_description": "量词错误：“一家人”本身已含量词“家”，前面不能再加“一个”。应说“他们一家人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
