INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99114, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同一家庭的成员。", "primary_collocate": null, "pronunciation": "yì jiā rén", "ipa": "i˥˩ tɕja˥ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "这张照片里是我们一家人。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是一家人，长得很像。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家人要互相帮助。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶生病了，一家人都很担心。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节的时候，一家人都穿上了新衣服。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一家人接到了城里。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家人的生日，妈妈都记得。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个国家，一家人常常住在一起。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家人吃完饭，爸爸去洗碗。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人在外面工作，养着一家人。", "target_word": "一家人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一家子", "label": "口语变体"}], "register": "中性", "sense_fingerprint": "名词：属于同一个家庭的所有成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc1bb5e-b14c-41de-8ff0-76ccf8bb8da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一家人", "is_correct": true, "explanation": "正确：“一家人”指同一家庭的成员，与“这张照片里是我们”相符。"}, {"text": "一个人", "is_correct": false, "explanation": "搭配：“我们”是复数，不能和“一个人”搭配。"}, {"text": "一棵树", "is_correct": false, "explanation": "语义：“我们”指人，不能说成一棵树。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“我们”指自己人，陌生人不能说成“我们”。"}], "explanations": {"一家人": "正确：“一家人”指同一家庭的成员，与“这张照片里是我们”相符。", "一个人": "搭配：“我们”是复数，不能和“一个人”搭配。", "一棵树": "语义：“我们”指人，不能说成一棵树。", "陌生人": "语义：“我们”指自己人，陌生人不能说成“我们”。"}, "sentence_index": 0, "correct_answer": "一家人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司一家人都很努力。", "explanation": "这里应该用〈同事〉。“一家人”指同一家庭的成员，不能指同公司的同事。"}, {"text": "门口站着很多一家人。", "explanation": "这里应该用〈家庭〉。“一家人”指一个家庭的成员；表示若干家庭要用“很多家庭”。"}, {"text": "他把一家人卖到了外地。", "explanation": "语义：“一家人”指家庭成员，是人而非物品，不能作“卖”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一家人", "is_correct": true, "explanation": "正确：“一家人的生日”指家里每位成员的生日，与“妈妈都记得”相符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有生日。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室没有生日，妈妈也不会记得它的生日。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“星期”是时间单位，不能作“生日”的所有者。"}], "explanations": {"一家人": "正确：“一家人的生日”指家里每位成员的生日，与“妈妈都记得”相符。", "窗户": "语义：窗户没有生日。", "教室": "语义：教室没有生日，妈妈也不会记得它的生日。", "星期": "搭配：“星期”是时间单位，不能作“生日”的所有者。"}, "sentence_index": 6, "correct_answer": "一家人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个一家人都在等车。", "explanation": "量词：数家庭要用量词“家”，应说“两家人”，不说“两个一家人”。"}, {"text": "我们小区一家人都很热情。", "explanation": "这里应该用〈邻居〉。“一家人”指家庭成员，不能指同一小区的邻居。"}, {"text": "他把一家人放进了冰箱里。", "explanation": "语义：“一家人”指家庭成员，是人，不能像东西一样“放进冰箱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
