INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99117, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年多是比一年长一点，不到两年。", "primary_collocate": null, "pronunciation": "yī nián duō", "ipa": "i˥ njɛn˧˥ twɔ˥", "syllable_count": 3, "sentences": [{"text": "我在北京住了一年多。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学中文已经一年多了。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们认识一年多了。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店开了一年多，生意很好。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在国外工作了一年多，上周回家了。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经一年多没见到爷爷了。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病一年多，现在好多了。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗来我家一年多了。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本书我看了一年多才看完。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们搬到这里一年多，邻居都认识了。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "比一年略长、不到两年的时间长度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b12da1c0-45be-4ff5-b000-71e282348403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99117, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一年多", "is_correct": true, "explanation": "正确。“住了”后接时段，“一年多”表示超过一年、不到两年的时长，符合句意。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指某一个年份，是时间点，不能说明“住了”持续了多长时间。"}, {"text": "一年前", "is_correct": false, "explanation": "搭配：“住了”后接时段，“一年前”指过去的某一时间点，不能说“住了一年前”。"}, {"text": "前年", "is_correct": false, "explanation": "语义：“前年”指两年前的那一年，是时间点，不能用作“住了”的时长补语。"}], "explanations": {"一年多": "正确。“住了”后接时段，“一年多”表示超过一年、不到两年的时长，符合句意。", "去年": "语义：“去年”指某一个年份，是时间点，不能说明“住了”持续了多长时间。", "一年前": "搭配：“住了”后接时段，“一年前”指过去的某一时间点，不能说“住了一年前”。", "前年": "语义：“前年”指两年前的那一年，是时间点，不能用作“住了”的时长补语。"}, "sentence_index": 0, "correct_answer": "一年多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不到一年多就学会了开车。", "explanation": "这里应该用〈不到一年〉。“不到”表示未满，而“一年多”表示超过一年，二者意思矛盾。"}, {"text": "这座桥一年多高。", "explanation": "“一年多”是时长，不能用来表示高度；应说“很高”或具体的米数。"}, {"text": "这件衣服一年多很便宜。", "explanation": "“一年多”是时长，不能用来描述价格；这里应说具体的金额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99117, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一年多", "is_correct": true, "explanation": "正确。“生病”后接一段时间，“一年多”表示超过一年、不到两年，符合句意。"}, {"text": "今年", "is_correct": false, "explanation": "语义：“今年”是当前所在的年份，是时间点，不能说明“生病”持续了多久。"}, {"text": "后年", "is_correct": false, "explanation": "语义：“后年”指两年后，是将来的时间点，与“生病”已经发生、现在已经好转的事实矛盾。"}, {"text": "半年前", "is_correct": false, "explanation": "搭配：“生病”后接时段，“半年前”指过去的某一时间点，不能说“生病半年前”。"}], "explanations": {"一年多": "正确。“生病”后接一段时间，“一年多”表示超过一年、不到两年，符合句意。", "今年": "语义：“今年”是当前所在的年份，是时间点，不能说明“生病”持续了多久。", "后年": "语义：“后年”指两年后，是将来的时间点，与“生病”已经发生、现在已经好转的事实矛盾。", "半年前": "搭配：“生病”后接时段，“半年前”指过去的某一时间点，不能说“生病半年前”。"}, "sentence_index": 6, "correct_answer": "一年多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的儿子已经一年多岁了。", "explanation": "“一年多”是时长，不能表示年龄；说年龄要用“一岁多”。"}, {"text": "这次活动已经一年多周年了。", "explanation": "“周年”指满整年的纪念，只能说“一周年”“两周年”，不能与“一年多”搭配；应说“已经一年多了”。"}, {"text": "他的身高是一年多。", "explanation": "“一年多”是时长，不能用来表示身高；说身高要用具体的长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在这里工作得一年多，已经很熟悉了。", "corrected_sentence": "他们在这里工作了一年多，已经很熟悉了。", "error_description": "错误：时量补语前用错了助词。表示动作完成后的时长应说“工作了一年多”，用“得”不能直接接时量词组，“得”后应接形容词或动词短语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的妹妹在学校学习得一年多，成绩进步很大。", "corrected_sentence": "我的妹妹在学校学习了一年多，成绩进步很大。", "error_description": "错误：“学习”后的“得”用错。“得”是补语标记，后面要接形容词或动词短语，不能直接接时量词组；表示完成的时长应用“了”，即“学习了一年多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
