INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99118, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "超过一年的时间。", "primary_collocate": null, "pronunciation": "yī nián duō", "ipa": "i˥ njɛn˧˥ twɔ˥", "syllable_count": 3, "sentences": [{"text": "一年多的时间里，他变了很多。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一年多，我学会了做饭。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年多过去了，他还记得那天。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年多对孩子来说，是很长的时间。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等了一年多，她终于收到信。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们花了一年多，才把花园种好。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去一年多，城市里新开了很多店。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在医院里住了一年多。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年多来，她每天都写日记。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年多的努力，换来了好成绩。", "target_word": "一年多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "超过一年的一段时间，可作主语、定语或时量补语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b12da1c0-45be-4ff5-b000-71e282348403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99118, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一年多", "is_correct": true, "explanation": "正确。“的时间里”需要一段时间，“一年多”表示超过一年的时长，符合句意。"}, {"text": "那一刻", "is_correct": false, "explanation": "语义：“那一刻”指极短的瞬间，不能与表示一段时间的“的时间里”搭配，与“变了很多”的长时段矛盾。"}, {"text": "元旦", "is_correct": false, "explanation": "语义：“元旦”指一个节日日期，是时间点，不能用来界定一段时间。"}, {"text": "年底", "is_correct": false, "explanation": "搭配：“年底”是某个时间点，“年底的时间里”不能表示一段持续的时间。"}], "explanations": {"一年多": "正确。“的时间里”需要一段时间，“一年多”表示超过一年的时长，符合句意。", "那一刻": "语义：“那一刻”指极短的瞬间，不能与表示一段时间的“的时间里”搭配，与“变了很多”的长时段矛盾。", "元旦": "语义：“元旦”指一个节日日期，是时间点，不能用来界定一段时间。", "年底": "搭配：“年底”是某个时间点，“年底的时间里”不能表示一段持续的时间。"}, "sentence_index": 0, "correct_answer": "一年多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河一年多深。", "explanation": "“一年多”是时长，不能用来表示深度；应说明具体的深度数量。"}, {"text": "他不到一年多就学会了游泳。", "explanation": "这里应该用〈不到一年〉。“不到”表示未满，而“一年多”表示超过一年，二者意思矛盾。"}, {"text": "他已经一年多岁了。", "explanation": "“一年多”是时长，不能表示年龄；说年龄要用“一岁多”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一年多", "is_correct": true, "explanation": "正确。“过去”后接一段已经过去的时间，“一年多”表示超过一年的时长，符合句意。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”指将来的时间，与表示回顾的“过去”矛盾。"}, {"text": "此刻", "is_correct": false, "explanation": "语义：“此刻”指当下，与表示已经过去的“过去”冲突。"}, {"text": "今晚", "is_correct": false, "explanation": "搭配：“过去”后接已经过去的时段，“今晚”是当前的时段，不能说“过去今晚”。"}], "explanations": {"一年多": "正确。“过去”后接一段已经过去的时间，“一年多”表示超过一年的时长，符合句意。", "明年": "语义：“明年”指将来的时间，与表示回顾的“过去”矛盾。", "此刻": "语义：“此刻”指当下，与表示已经过去的“过去”冲突。", "今晚": "搭配：“过去”后接已经过去的时段，“今晚”是当前的时段，不能说“过去今晚”。"}, "sentence_index": 6, "correct_answer": "一年多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在一年多点钟到达了车站。", "explanation": "这里应该用〈几点钟〉。“一年多”是时长，不能表示钟点，说时刻要用“几点钟”之类。"}, {"text": "这个学校已经一年多周年了，大家一起庆祝。", "explanation": "“周年”指满整年的纪念，只能说“一周年”“两周年”，不能与“一年多”搭配。"}, {"text": "这块石头重一年多。", "explanation": "“一年多”是时长，不能表示重量；说重量要用具体的斤两或公斤数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们为这件事等着一年多，终于有了结果。", "corrected_sentence": "我们为这件事等了一年多，终于有了结果。", "error_description": "错误：动词后的助词用错。表示动作完成后的时长应说“等了一年多”，用“着”表示持续状态，不能直接接时量词组。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天练习，坚持得一年多，终于拿到了冠军。", "corrected_sentence": "她每天练习，坚持了一年多，终于拿到了冠军。", "error_description": "错误：动词后的助词用错。“坚持”后表示时长应用“了”，即“坚持了一年多”；“得”是补语标记，后面要接形容词或动词短语，不能直接接时量词组。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
