INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99125, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "上相是拍出来的照片比真人还好看。", "primary_collocate": null, "pronunciation": "shàng xiàng", "ipa": "ʂɑŋ˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你的妹妹真上相，照片像明星一样。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件红衣服让她更上相。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不上相，照片里看起来很累。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我很上相，让我多拍几张。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大眼睛的人通常比较上相。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她本人一般，照片却很上相。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天拍的照片真好看，你太上相了。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他又高又瘦，拍出来很上相。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想上相的话，要找好光线。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我奶奶很上相，年轻时的照片特别美。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "照片里的样子比真人更漂亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3997216-d3ae-4dcb-ab5c-3abc7b75bba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99125, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上相", "is_correct": true, "explanation": "目标词：照片里的样子比真人更好看。"}, {"text": "上香", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是烧香。"}, {"text": "上线", "is_correct": false, "explanation": "xiàn 与 xiàng 的韵尾不同（n 与 ng），意思是上网或产品上市。"}, {"text": "上限", "is_correct": false, "explanation": "xiàn 与 xiàng 的韵尾不同（n 与 ng），意思是最高限度。"}, {"text": "上下", "is_correct": false, "explanation": "第二个音节少了韵尾 ng，读作 xià，意思是上面和下面。"}], "explanations": {"上相": "目标词：照片里的样子比真人更好看。", "上香": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是烧香。", "上线": "xiàn 与 xiàng 的韵尾不同（n 与 ng），意思是上网或产品上市。", "上限": "xiàn 与 xiàng 的韵尾不同（n 与 ng），意思是最高限度。", "上下": "第二个音节少了韵尾 ng，读作 xià，意思是上面和下面。"}, "sentence_index": null, "correct_answer": "上相"}, "level_3": {"options": [{"text": "上相", "is_correct": true, "explanation": "“照片像明星一样”说明评价的是拍照效果，上相与之相符。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：“好吃”说的是食物的味道，不能用来形容人，和“照片像明星”冲突。"}, {"text": "耐用", "is_correct": false, "explanation": "语义：“耐用”说的是物品经久不坏，不能用来评价人的样子。"}, {"text": "好闻", "is_correct": false, "explanation": "搭配：“好闻”说气味，不能用来形容人的长相或照片效果。"}], "explanations": {"上相": "“照片像明星一样”说明评价的是拍照效果，上相与之相符。", "好吃": "语义：“好吃”说的是食物的味道，不能用来形容人，和“照片像明星”冲突。", "耐用": "语义：“耐用”说的是物品经久不坏，不能用来评价人的样子。", "好闻": "搭配：“好闻”说气味，不能用来形容人的长相或照片效果。"}, "sentence_index": 0, "correct_answer": "上相"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段音乐很上相，我每天都想再听一遍。", "explanation": "这里应该用〈好听〉。上相只说人或物在照片里的效果，评价声音要用〈好听〉。"}, {"text": "这个段子很上相，大家都笑个不停。", "explanation": "这里应该用〈好笑〉。上相指拍照效果，段子是否让人发笑要用〈好笑〉。"}, {"text": "他很上相，成绩总是班里第一。", "explanation": "这里应该用〈聪明〉。上相只说照片里的样子，不能用来说学习成绩或智力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99125, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上相", "is_correct": true, "explanation": "“真好看”的照片与“你太上相了”同说拍照效果，语义连贯。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”说的是味道，和“照片真好看”的评价无关。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用来形容人的样子。"}, {"text": "腥", "is_correct": false, "explanation": "语义：“腥”说的是气味或味道，与对照片的赞美相冲突。"}], "explanations": {"上相": "“真好看”的照片与“你太上相了”同说拍照效果，语义连贯。", "咸": "语义：“咸”说的是味道，和“照片真好看”的评价无关。", "清脆": "搭配：“清脆”形容声音，不能用来形容人的样子。", "腥": "语义：“腥”说的是气味或味道，与对照片的赞美相冲突。"}, "sentence_index": 6, "correct_answer": "上相"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章写得很上相，同学们都想读。", "explanation": "这里应该用〈好看〉。上相只指人或物拍照后的效果，评价文章的写法要用〈好看〉。"}, {"text": "这封信写得很上相，妈妈看了很感动。", "explanation": "这里应该用〈漂亮〉。上相指拍照后显得好看，写字或写信的美观要用〈漂亮〉。"}, {"text": "他很上相，从不说谎。", "explanation": "这里应该用〈诚实〉。上相只说照片里的样子，不能用来描述品行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99125, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是个很上相人，拍什么都好看。", "corrected_sentence": "她是个很上相的人，拍什么都好看。", "error_description": "“上相”修饰名词时中间要加“的”，应说“很上相的人”，不能说“很上相人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99125, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他拍照拍很上相，朋友都夸他。", "corrected_sentence": "他拍照拍得很上相，朋友都夸他。", "error_description": "“拍”和“上相”之间需要补语标记“得”，应说“拍得很上相”，不能说“拍很上相”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
