INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99126, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "拍照时显得比实际更好看。", "primary_collocate": null, "pronunciation": "shàng xiàng", "ipa": "ʂɑŋ˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "她长得一般，但是很上相。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥不太上相，照片总是不好看。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你真上相，这张照片比真人好看。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很上相，拍什么都像明星。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友一点也不上相，真人比照片好看。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么我拍照总是不上相？", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的脸小，所以特别上相。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女孩本人一般，但照片特别上相。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说圆脸的人比较上相。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他本人很普通，可是一拍照就上相。", "target_word": "上相", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "人拍照时看起来比本人好看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3997216-d3ae-4dcb-ab5c-3abc7b75bba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
