ED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上相", "is_correct": true, "explanation": "“脸小”与拍照效果有关，“特别上相”说拍照效果好，语义连贯。"}, {"text": "好闻", "is_correct": false, "explanation": "搭配：“好闻”说气味，不能用来形容人的脸或拍照效果。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”说的是味道，和“脸小”没有关系。"}, {"text": "腥", "is_correct": false, "explanation": "语义：“腥”说的是气味或味道，不能用来形容人的外貌。"}], "explanations": {"上相": "“脸小”与拍照效果有关，“特别上相”说拍照效果好，语义连贯。", "好闻": "搭配：“好闻”说气味，不能用来形容人的脸或拍照效果。", "咸": "语义：“咸”说的是味道，和“脸小”没有关系。", "腥": "语义：“腥”说的是气味或味道，不能用来形容人的外貌。"}, "sentence_index": 6, "correct_answer": "上相"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章写得很上相，结构也很清楚。", "explanation": "这里应该用〈好看〉。上相只指人或物拍照后的效果，评价文章的写法要用〈好看〉。"}, {"text": "这封信写得很上相，妈妈看了很感动。", "explanation": "这里应该用〈漂亮〉。上相指拍照后显得好看，写字或写信的美观要用〈漂亮〉。"}, {"text": "他很上相，经常帮助别人。", "explanation": "这里应该用〈善良〉。上相只说照片里的样子好看，不能用来描述品行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很上相着，照片都很好看。", "corrected_sentence": "她很上相，照片都很好看。", "error_description": "“上相”是形容词，后面不能加“着”。错误形式是“很上相着”，正确形式是“很上相”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟本人很普通，可是拍照很上相得。", "corrected_sentence": "我弟弟本人很普通，可是拍照很上相。", "error_description": "“上相”是形容词，后面不能直接加“得”作补语。错误形式是“很上相得”，正确形式是“很上相”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
